-- en: "The condition ordering controls are arrows and draggable rows in the sidebar of the selected category. In Manage categories, the same controls order the categories themselves."
L["The condition ordering controls are arrows and draggable rows in the sidebar of the selected category. In Manage categories, the same controls order the categories themselves."] = "Os controles de ordenação das condições são as setas e as linhas arrastáveis na barra lateral da categoria selecionada. Em Gerenciar categorias, os mesmos controles ordenam as próprias categorias."
-- en: "Apply changes before leaving this page?"
L["Apply changes before leaving this page?"] = "Aplicar as alterações antes de sair desta página?"
-- en: "Apply or discard current settings before opening the custom code editor."
L["Apply or discard current settings before opening the custom code editor."] = "Aplique ou descarte as configurações atuais antes de abrir o editor de código personalizado."
-- en: "Apply item-set changes before binding it to an action bar."
L["Apply item-set changes before binding it to an action bar."] = "Aplique as alterações do conjunto de itens antes de vinculá-lo a uma barra de ações."
-- en: "Choose a new named copy or replace the selected editable entry. Review the destination before importing."
L["Choose a new named copy or replace the selected editable entry. Review the destination before importing."] = "Escolha uma nova cópia nomeada ou substitua a entrada editável selecionada. Revise o destino antes de importar."
-- en: "Clear"
L["Clear"] = "Limpar"
-- en: "Confirm the Lua import, then review it before saving."
L["Confirm the Lua import, then review it before saving."] = "Confirme a importação de Lua e revise-a antes de salvar."
-- en: "IMPORTED_CONDITION"
L["IMPORTED_CONDITION"] = "IMPORTED_CONDITION"
