-- en: "Name not supplied"
L["Name not supplied"] = "Nome não informado"
-- en: "Original name"
L["Original name"] = "Nome original"
-- en: "Ready to import. Choose replacement or a named copy."
L["Ready to import. Choose replacement or a named copy."] = "Pronto para importar. Escolha substituir ou uma cópia nomeada."
-- en: "Replace selected entry"
L["Replace selected entry"] = "Substituir a entrada selecionada"
-- en: "That condition identifier already exists."
L["That condition identifier already exists."] = "Esse identificador de condição já existe."
-- en: "The selected profile changed. Reopen the import window."
L["The selected profile changed. Reopen the import window."] = "O perfil selecionado mudou. Abra novamente a janela de importação."
-- en: "This import contains Lua code. Only continue if you trust its author. Import opens the code for review; saving the condition can execute it."
L["This import contains Lua code. Only continue if you trust its author. Import opens the code for review; saving the condition can execute it."] = "Esta importação contém código Lua. Continue apenas se você confia no autor. Importar abre o código para revisão; salvar a condição pode executá-lo."
-- en: "Use letters, numbers and underscores for the condition identifier."
L["Use letters, numbers and underscores for the condition identifier."] = "Use letras, números e sublinhados no identificador da condição."
-- en: "Check %s: %s"
L["Check %s: %s"] = "Verificar %s: %s"
-- en: "Check syntax"
L["Check syntax"] = "Verificar sintaxe"
-- en: "Choose icon"
L["Choose icon"] = "Escolher ícone"
-- en: "Custom Lua has the same access as the addon. Only import code you trust. Syntax validation cannot establish that a callback is safe or correct. Existing custom widget callbacks still use their original UI contract."
L["Custom Lua has the same access as the addon. Only import code you trust. Syntax validation cannot establish that a callback is safe or correct. Existing custom widget callbacks still use their original UI contract."] = "O Lua personalizado tem o mesmo acesso que o addon. Importe apenas código em que você confia. A validação de sintaxe não consegue garantir que um callback seja seguro ou correto. Os callbacks de widget personalizados existentes continuam usando o contrato de interface original."
-- en: "Declare named fields, primitive types, nested records and unions. Example: { spell = { string, number }, unit = string, tests = condition[] }. Schema text is parsed as data and never evaluated as Lua."
L["Declare named fields, primitive types, nested records and unions. Example: { spell = { string, number }, unit = string, tests = condition[] }. Schema text is parsed as data and never evaluated as Lua."] = "Declare campos nomeados, tipos primitivos, registros aninhados e uniões. Exemplo: { spell = { string, number }, unit = string, tests = condition[] }. O texto do esquema é analisado como dados e nunca é avaliado como Lua."
-- en: "Definition"
L["Definition"] = "Definição"
-- en: "Editing code"
L["Editing code"] = "Edição de código"
-- en: "Evaluate"
L["Evaluate"] = "Avaliar"
-- en: "Field schema"
L["Field schema"] = "Esquema de campos"
-- en: "Fields UI"
L["Fields UI"] = "Interface de campos"
-- en: "Function tabs edit separate callbacks. Changes stay in a draft. Check syntax compiles every callback without running it. Apply registers the callbacks and can run registration code. Cancel discards the draft. Undo and Redo work across function tabs."
L["Function tabs edit separate callbacks. Changes stay in a draft. Check syntax compiles every callback without running it. Apply registers the callbacks and can run registration code. Cancel discards the draft. Undo and Redo work across function tabs."] = "As abas de funções editam callbacks separados. As alterações ficam em um rascunho. Verificar sintaxe compila todos os callbacks sem executá-los. Aplicar registra os callbacks e pode executar código de registro. Cancelar descarta o rascunho. Desfazer e Refazer funcionam em todas as abas de funções."
-- en: "On register"
L["On register"] = "Ao registrar"
-- en: "On unregister"
L["On unregister"] = "Ao cancelar o registro"
-- en: "Summary"
L["Summary"] = "Resumo"
-- en: "Syntax checked. No custom code was executed."
L["Syntax checked. No custom code was executed."] = "Sintaxe verificada. Nenhum código personalizado foi executado."
-- en: "The custom condition changed elsewhere. Reopen it before saving."
L["The custom condition changed elsewhere. Reopen it before saving."] = "A condição personalizada foi alterada em outro lugar. Abra-a novamente antes de salvar."
-- en: "Trusted code"
L["Trusted code"] = "Código confiável"
-- en: "Validate"
L["Validate"] = "Validar"
-- en: "All tags"
L["All tags"] = "Todas as etiquetas"
-- en: "Edit the description, tags, author, realm, email, website and version. Source citations remain separate from your attribution. Use changes updates the rotation draft; Apply the rotation to save it. Cancel or Escape restores this dialog’s opening values."
L["Edit the description, tags, author, realm, email, website and version. Source citations remain separate from your attribution. Use changes updates the rotation draft; Apply the rotation to save it. Cancel or Escape restores this dialog’s opening values."] = "Edite a descrição, as etiquetas, o autor, o reino, o e-mail, o site e a versão. As citações de fontes ficam separadas da sua autoria. Usar alterações atualiza o rascunho da rotação; aplique a rotação para salvá-la. Cancelar ou Esc restaura os valores que esta caixa de diálogo tinha ao abrir."
-- en: "Invalid tags. Use up to 64 tags of 64 characters, separated by commas."
L["Invalid tags. Use up to 64 tags of 64 characters, separated by commas."] = "Etiquetas inválidas. Use até 64 etiquetas de 64 caracteres, separadas por vírgulas."
-- en: "Separate tags with commas. Use quotes for tags containing commas. Any personal label is allowed."
L["Separate tags with commas. Use quotes for tags containing commas. Any personal label is allowed."] = "Separe as etiquetas com vírgulas. Use aspas para etiquetas que contenham vírgulas. Qualquer rótulo pessoal é permitido."
-- en: "Tags"
L["Tags"] = "Etiquetas"
-- en: "Switch priority"
L["Switch priority"] = "Prioridade de troca"
-- en: "Priority %d"
L["Priority %d"] = "Prioridade %d"
-- en: "Invalid priority"
L["Invalid priority"] = "Prioridade inválida"
-- en: "Switch priority must be a whole number between -100000 and 100000."
L["Switch priority must be a whole number between -100000 and 100000."] = "A prioridade de troca deve ser um número inteiro entre -100000 e 100000."
-- en: "Edit the description, tags, switch priority, author, realm, email, website and version. Source citations remain separate from your attribution. Use changes updates the rotation draft; Apply the rotation to save it. Cancel or Escape restores this dialog’s opening values."
L["Edit the description, tags, switch priority, author, realm, email, website and version. Source citations remain separate from your attribution. Use changes updates the rotation draft; Apply the rotation to save it. Cancel or Escape restores this dialog’s opening values."] = "Edite a descrição, as etiquetas, a prioridade de troca, o autor, o reino, o e-mail, o site e a versão. As citações de fontes ficam separadas da sua autoria. Usar alterações atualiza o rascunho da rotação; aplique a rotação para salvá-la. Cancelar ou Esc restaura os valores que esta caixa de diálogo tinha ao abrir."
-- en: "Higher priority wins within custom or Built In rotations. Custom rotations and a valid saved fallback take precedence over Built In rotations. Equal priorities use name, then identity. Blank means zero."
L["Higher priority wins within custom or Built In rotations. Custom rotations and a valid saved fallback take precedence over Built In rotations. Equal priorities use name, then identity. Blank means zero."] = "A prioridade mais alta vence entre rotações personalizadas ou entre integradas. Rotações personalizadas e uma rotação reserva salva válida têm precedência sobre as integradas. Prioridades iguais usam o nome e depois a identidade. Em branco significa zero."
-- en: "Invalid switch priority for %s:%s; explicit repair resets it to zero."
L["Invalid switch priority for %s:%s; explicit repair resets it to zero."] = "Prioridade de troca inválida em %s:%s; um reparo explícito a redefine para zero."
-- en: "Match all ranks"
L["Match all ranks"] = "Corresponder a todos os graus"
-- en: "%s (any rank)"
L["%s (any rank)"] = "%s (qualquer grau)"
-- en: "For a numeric spell selection, also recognize auras with the same readable localized spell name. Exact IDs remain the default. Spell names already match by name. Unavailable metadata or restricted aura identity stays unavailable, including under NOT. Different spells sharing a name can match; use exact IDs when that distinction matters."
L["For a numeric spell selection, also recognize auras with the same readable localized spell name. Exact IDs remain the default. Spell names already match by name. Unavailable metadata or restricted aura identity stays unavailable, including under NOT. Different spells sharing a name can match; use exact IDs when that distinction matters."] = "Para uma seleção numérica de feitiço, reconhece também auras com o mesmo nome de feitiço localizado legível. IDs exatos continuam sendo o padrão. Nomes de feitiço já correspondem pelo nome. Metadados indisponíveis ou identidade de aura restrita continuam indisponíveis, inclusive sob NÃO. Feitiços diferentes com o mesmo nome podem corresponder; use IDs exatos quando essa distinção importar."
-- en: "Talent tree %s"
L["Talent tree %s"] = "Árvore de talentos %s"
-- en: "This client does not expose a Classic talent-tree layout. The saved tree reference is preserved."
L["This client does not expose a Classic talent-tree layout. The saved tree reference is preserved."] = "Este cliente não expõe um layout de árvore de talentos do Classic. A referência à árvore salva é preservada."
-- en: "Talent tree"
L["Talent tree"] = "Árvore de talentos"
-- en: "Talent Tree Points"
L["Talent Tree Points"] = "Pontos na árvore de talentos"
-- en: "points spent in %s"
L["points spent in %s"] = "pontos gastos em %s"
-- en: "Talent tree selects the Classic tree whose spent points are compared. Public points are read again on the next evaluation; missing or restricted points are unavailable, including under NOT. Grids and trait trees are unsupported."
L["Talent tree selects the Classic tree whose spent points are compared. Public points are read again on the next evaluation; missing or restricted points are unavailable, including under NOT. Grids and trait trees are unsupported."] = "Árvore de talentos seleciona a árvore do Classic cujos pontos gastos são comparados. Os pontos públicos são lidos novamente na próxima avaliação; pontos ausentes ou restritos ficam indisponíveis, inclusive sob NÃO. Grades e árvores de traços não são suportadas."
-- en: "Compare whole points spent from zero to 512. An explicit comparison with zero can describe an unspent tree."
L["Compare whole points spent from zero to 512. An explicit comparison with zero can describe an unspent tree."] = "Compara pontos gastos inteiros de zero a 512. Uma comparação explícita com zero pode descrever uma árvore sem pontos gastos."
-- en: "Primary Talent Tree"
L["Primary Talent Tree"] = "Árvore de talentos principal"
-- en: "your primary talent tree is %s"
L["your primary talent tree is %s"] = "sua árvore de talentos principal é %s"
-- en: "Talent tree selects the unique Classic tree with the most positive spent points. Equal maxima, no spent points, missing records and restricted points are unavailable, including under NOT."
L["Talent tree selects the unique Classic tree with the most positive spent points. Equal maxima, no spent points, missing records and restricted points are unavailable, including under NOT."] = "Árvore de talentos seleciona a única árvore do Classic com mais pontos gastos, desde que positivos. Máximos empatados, nenhum ponto gasto, registros ausentes e pontos restritos ficam indisponíveis, inclusive sob NÃO."
-- en: "The primary tree is derived from readable points, not the saved rotation slot. Hybrid builds may need tree-point or individual-talent conditions instead; the primary tree does not assign a tank or healer role. Grids and trait trees are unsupported."
L["The primary tree is derived from readable points, not the saved rotation slot. Hybrid builds may need tree-point or individual-talent conditions instead; the primary tree does not assign a tank or healer role. Grids and trait trees are unsupported."] = "A árvore principal é derivada dos pontos legíveis, não do espaço de rotação salvo. Builds híbridas podem precisar de condições de pontos na árvore ou de talentos individuais; a árvore principal não atribui a função de tanque ou curador. Grades e árvores de traços não são suportadas."
-- en: "Item sets are checked in priority order. Bag counts use the first carried candidate, not the sum. Availability, range and cooldown checks use the first carried or equipped candidate. Missing or restricted observations stay unavailable, including under NOT."
L["Item sets are checked in priority order. Bag counts use the first carried candidate, not the sum. Availability, range and cooldown checks use the first carried or equipped candidate. Missing or restricted observations stay unavailable, including under NOT."] = "Os conjuntos de itens são verificados em ordem de prioridade. As contagens de bolsa usam o primeiro candidato carregado, não a soma. As verificações de disponibilidade, alcance e tempo de recarga usam o primeiro candidato carregado ou equipado. Observações ausentes ou restritas continuam indisponíveis, inclusive sob NÃO."
-- en: "Item Available checks the required level and enabled item cooldown. An active cooldown qualifies only when it ends with the readable global cooldown. This condition does not bypass the action's implicit ownership, usability and range checks."
L["Item Available checks the required level and enabled item cooldown. An active cooldown qualifies only when it ends with the readable global cooldown. This condition does not bypass the action's implicit ownership, usability and range checks."] = "Item disponível verifica o nível exigido e o tempo de recarga ativo do item. Um tempo de recarga em andamento só conta quando termina junto com o tempo de recarga global legível. Esta condição não ignora as verificações implícitas de posse, usabilidade e alcance da ação."
-- en: "Diagram view"
L["Diagram view"] = "Visualização em diagrama"
-- en: "List view"
L["List view"] = "Visualização em lista"
-- en: "Switch between the diagram and compact tree list. This changes only the view."
L["Switch between the diagram and compact tree list. This changes only the view."] = "Alterna entre o diagrama e a lista compacta em árvore. Altera apenas a visualização."
-- en: "Zoom out"
L["Zoom out"] = "Diminuir zoom"
-- en: "Zoom in"
L["Zoom in"] = "Aumentar zoom"
-- en: "Reset canvas zoom to 100%. Drag empty canvas space to pan. Window scale is unchanged."
L["Reset canvas zoom to 100%. Drag empty canvas space to pan. Window scale is unchanged."] = "Redefine o zoom da área de desenho para 100%. Arraste o espaço vazio da área de desenho para deslocar. A escala da janela não muda."
-- en: "Navigating rotations"
L["Navigating rotations"] = "Navegando pelas rotações"
-- en: "Diagram / List changes only the rotation view; General settings choose the default. Diagram has floating minus, percentage and plus controls at the bottom right. Scroll to zoom from 25% to 200%; click the percentage or middle-click to reset to 100%. Drag empty diagram space to pan. List uses normal scrollbars with touching cards and boxed branch arms, False before True. Cooldowns use a separate scrolling grid. Dragging cards reorders them in every view. Each workspace currently shows at most 200 cards; the remaining saved cards are preserved."
L["Diagram / List changes only the rotation view; General settings choose the default. Diagram has floating minus, percentage and plus controls at the bottom right. Scroll to zoom from 25% to 200%; click the percentage or middle-click to reset to 100%. Drag empty diagram space to pan. List uses normal scrollbars with touching cards and boxed branch arms, False before True. Cooldowns use a separate scrolling grid. Dragging cards reorders them in every view. Each workspace currently shows at most 200 cards; the remaining saved cards are preserved."] = "Diagrama / Lista altera apenas a visualização da rotação; as configurações gerais escolhem o padrão. O diagrama tem controles flutuantes de menos, porcentagem e mais no canto inferior direito. Role para aplicar zoom de 25% a 200%; clique na porcentagem ou com o botão do meio para voltar a 100%. Arraste o espaço vazio do diagrama para deslocar. Lista usa barras de rolagem normais, com cartões encostados e braços de ramificação em caixas, Falso antes de Verdadeiro. Os tempos de recarga usam uma grade com rolagem separada. Arrastar cartões os reordena em todas as visualizações. Cada espaço de trabalho mostra no momento no máximo 200 cartões; os demais cartões salvos são preservados."
-- en: "Enabled / Disabled"
L["Enabled / Disabled"] = "Ativado / Desativado"
-- en: "Announcement substitutions"
L["Announcement substitutions"] = "Substituições de anúncio"
-- en: "New, Duplicate, Import/Export and Compare"
L["New, Duplicate, Import/Export and Compare"] = "Novo, Duplicar, Importar/exportar e Comparar"
-- en: "Announcement details stay always expanded while editing. Press Enter or leave a text field to stage its value; Apply saves the draft. Invalid fields must be corrected before Apply; Discard abandons pending changes. Searchable selectors open on click and filter as you type. The page Help icon explains every option and text substitution."
L["Help.Announces.editing"] = "Os detalhes do anúncio ficam sempre expandidos durante a edição. Pressione Enter ou saia de um campo de texto para preparar o valor; Aplicar salva o rascunho. Campos inválidos precisam ser corrigidos antes de Aplicar; Descartar abandona as alterações pendentes. Seletores com busca abrem ao clicar e filtram enquanto você digita. O ícone de Ajuda da página explica cada opção e cada substituição de texto."
-- en: "Announce selected spell casts or item uses independently of your active rotation, or invoke a configured Via Script/Macro entry directly. Select an entry in the sidebar, or use New to prepare one. The trigger applies to every ordered output card; each card has its own destination and conditions. These settings do not cast spells or use items. Cast-triggered announcements follow RM's combat-data policy and do not run on reference-only clients."
L["Help.Announces.overview"] = "Anuncie lançamentos de feitiços ou usos de itens selecionados independentemente da sua rotação ativa, ou invoque diretamente uma entrada configurada Via script/macro. Selecione uma entrada na barra lateral ou use Novo para preparar uma. O gatilho se aplica a cada cartão de saída ordenado; cada cartão tem o próprio destino e as próprias condições. Estas configurações não lançam feitiços nem usam itens. Anúncios acionados por lançamento seguem a política de dados de combate do RM e não são executados em clientes apenas de referência."
-- en: "An optional name identifies this announcement in the sidebar. Without one, the action name or Via Script/Macro identifier is used. Changing this display name does not change the watched action or callable identifier."
L["Help.Announces.name"] = "Um nome opcional identifica este anúncio na barra lateral. Sem ele, é usado o nome da ação ou o identificador Via script/macro. Alterar este nome de exibição não altera a ação observada nem o identificador invocável."
-- en: "Choose Spell, Pet Spell, Item or Via Script/Macro. Changing type clears the previous action and exact-rank choice. Via Script/Macro uses an Identifier instead of a cast event or stored action; switching back restores the event selector. Choosing the current type keeps its fields."
L["Help.Announces.type"] = "Escolha Feitiço, Feitiço de ajudante, Item ou Via script/macro. Alterar o tipo limpa a ação anterior e a escolha de grau exato. Via script/macro usa um Identificador em vez de um evento de lançamento ou de uma ação armazenada; voltar ao tipo anterior restaura o seletor de eventos. Escolher o tipo atual mantém os campos."
-- en: "Watch one of your spells. Choose the spell in the searchable field below Action Type."
L["Help.Announces.type.spell"] = "Observa um dos seus feitiços. Escolha o feitiço no campo com busca abaixo de Tipo de ação."
-- en: "Watch a spell from your pet spellbook. The spell selector uses the pet catalog for this action type."
L["Help.Announces.type.pet"] = "Observa um feitiço do grimório do seu ajudante. O seletor de feitiços usa o catálogo do ajudante para este tipo de ação."
-- en: "Watch item-use spells from a reusable item set or a custom list. This is an announcement trigger; it does not choose an item to use for you."
L["Help.Announces.type.item"] = "Observa os feitiços de uso de itens de um conjunto de itens reutilizável ou de uma lista personalizada. Este é um gatilho de anúncio; ele não escolhe um item para você usar."
-- en: "Search by spell name, select a result, or drag a spell from your spellbook or action bar into the field. The icon and name identify the selected spell. Spell and pet spell choices keep their respective catalog scope."
L["Help.Announces.spell"] = "Busque pelo nome do feitiço, selecione um resultado ou arraste um feitiço do seu grimório ou da sua barra de ações para o campo. O ícone e o nome identificam o feitiço selecionado. As escolhas de feitiço e de feitiço de ajudante mantêm o escopo do respectivo catálogo."
-- en: "Checked limits matching to the selected rank. Unchecked includes the known ranks in that spell family. This checkbox is shown only for Spell and Pet Spell."
L["Help.Announces.ranked"] = "Marcado, limita as correspondências ao grau selecionado. Desmarcado, inclui os graus conhecidos dessa família de feitiços. Esta caixa de seleção aparece apenas para Feitiço e Feitiço de ajudante."
-- en: "Choose a reusable set, or Custom to edit this announcement's own list. For a custom list, search for or drag items into the fields; Add item appends one and a red trash can removes an entry. Any matching item-use spell in the list can trigger the announcement; list order does not limit announcements to the first carried item. Changes to a shared set belong on the Item Sets page."
L["Help.Announces.items"] = "Escolha um conjunto reutilizável, ou Personalizado para editar a lista própria deste anúncio. Em uma lista personalizada, busque ou arraste itens para os campos; Adicionar item acrescenta um ao final e a lixeira vermelha remove uma entrada. Qualquer feitiço de uso de item correspondente na lista pode acionar o anúncio; a ordem da lista não limita os anúncios ao primeiro item carregado. Alterações em um conjunto compartilhado são feitas na página Conjuntos de itens."
-- en: "For automatic action types, choose which observed cast event triggers this entry. A start, stop, interruption, failure or delay is different from a successful cast. Client support determines which events and observations are available. Via Script/Macro has no cast event."
L["Help.Announces.event"] = "Nos tipos de ação automáticos, escolha qual evento de lançamento observado aciona esta entrada. Início, parada, interrupção, falha ou atraso são diferentes de um lançamento bem-sucedido. O suporte do cliente determina quais eventos e observações estão disponíveis. Via script/macro não tem evento de lançamento."
-- en: "The cast or channel started. This event does not mean it will finish successfully."
L["Help.Announces.event.START"] = "O lançamento ou a canalização começou. Este evento não significa que terminará com sucesso."
-- en: "The cast or channel stopped. A stop alone does not establish whether it succeeded."
L["Help.Announces.event.STOP"] = "O lançamento ou a canalização parou. Uma parada por si só não indica se houve sucesso."
-- en: "The client reported a successful spell cast or item-use spell. For a channel, this can occur as channeling begins rather than after its final tick."
L["Help.Announces.event.SUCCEEDED"] = "O cliente informou um lançamento de feitiço ou de feitiço de uso de item bem-sucedido. Em uma canalização, isso pode ocorrer quando ela começa, e não após o último tique."
-- en: "The client reported that the cast was interrupted. This can include cancelling a cast yourself."
L["Help.Announces.event.INTERRUPTED"] = "O cliente informou que o lançamento foi interrompido. Isso pode incluir você mesmo cancelar um lançamento."
-- en: "The client reported that the cast failed. This is separate from the successful-cast event."
L["Help.Announces.event.FAILED"] = "O cliente informou que o lançamento falhou. Isso é separado do evento de lançamento bem-sucedido."
-- en: "The client reported a delay to the cast. This event is not a completion or success notification."
L["Help.Announces.event.DELAYED"] = "O cliente informou um atraso no lançamento. Este evento não é uma notificação de conclusão nem de sucesso."
-- en: "Choose a chat destination, local output, a named Emote or Audible. Emote replaces Text with an emote selector and optional recipient. Audible replaces Text with Sound. Text is retained when switching modes. Say, Yell, Whisper and named joined channels are offered only for Via Script/Macro and remain subject to native restrictions."
L["Help.Announces.announce"] = "Escolha um destino de bate-papo, a saída local, um emote nomeado ou Sonoro. Emote substitui Texto por um seletor de emotes e um destinatário opcional. Sonoro substitui Texto por Som. O texto é mantido ao trocar de modo. Dizer, Gritar, Sussurrar e canais nomeados em que você entrou são oferecidos apenas para Via script/macro e continuam sujeitos às restrições nativas."
-- en: "Play the selected sound locally on the Master audio channel; no chat message is sent. Choose an available sound before applying the announcement."
L["Help.Announces.channel.audible"] = "Reproduz o som selecionado localmente no canal de áudio principal; nenhuma mensagem de bate-papo é enviada. Escolha um som disponível antes de aplicar o anúncio."
-- en: "Use raid chat while in a raid, party chat while in a party, or your local chat frame while solo."
L["Help.Announces.channel.partyraid"] = "Usa o bate-papo de raide quando em uma raide, o de grupo quando em um grupo ou sua janela de bate-papo local quando sozinho."
-- en: "Use party chat when grouped, including your party within a raid. This destination produces no solo chat message."
L["Help.Announces.channel.party"] = "Usa o bate-papo de grupo quando agrupado, incluindo seu grupo dentro de uma raide. Este destino não gera mensagem de bate-papo quando você está sozinho."
-- en: "Request group warning output. Depending on group membership and permissions, RM may use raid chat, party chat, or local output instead."
L["Help.Announces.channel.raidwarn"] = "Solicita uma saída de aviso de grupo. Dependendo da participação no grupo e das permissões, o RM pode usar o bate-papo de raide, de grupo ou a saída local."
-- en: "A saved free-text emote keeps its original message. Select Emote to use a named client emote instead."
L["Help.Announces.channel.emote"] = "Um emote de texto livre salvo mantém a mensagem original. Selecione Emote para usar um emote nomeado do cliente."
-- en: "Custom emote"
L["Custom emote"] = "Emote personalizado"
-- en: "Use spell recipient ({{target}})"
L["Use spell recipient ({{target}})"] = "Usar o destinatário do feitiço ({{target}})"
-- en: "Automatic Say and Yell are unavailable. Choose another announcement destination."
L["Automatic Say and Yell are unavailable. Choose another announcement destination."] = "Dizer e Gritar automáticos estão indisponíveis. Escolha outro destino para o anúncio."
-- en: "Choose a named emote from this client's slash commands, such as /cheer. This does not send the Text field as a custom emote."
L["Help.Announces.channel.gesture"] = "Escolha um emote nomeado dos comandos de barra deste cliente, como /cheer. Isso não envia o campo Texto como um emote personalizado."
-- en: "Choose the emote to perform when the configured cast event is observed. The client may restrict an emote or require a hardware action; RM does not retry through another output path."
L["Help.Announces.emote"] = "Escolha o emote a executar quando o evento de lançamento configurado for observado. O cliente pode restringir um emote ou exigir uma ação de hardware; o RM não tenta de novo por outro caminho de saída."
-- en: "For cast entries, checked directs the emote to the recipient recorded for this exact cast, including click casting. It does not use your current target or a previous cast's recipient. For Via Script/Macro, checked uses the supplied macro unit. A missing recipient skips targeted output. Unchecked performs the emote without a target."
L["Help.Announces.emote_target"] = "Em entradas de lançamento, marcado direciona o emote ao destinatário registrado para esse lançamento exato, incluindo lançamento por clique. Não usa seu alvo atual nem o destinatário de um lançamento anterior. Em Via script/macro, marcado usa a unidade da macro fornecida. Sem destinatário, a saída direcionada é ignorada. Desmarcado executa o emote sem alvo."
-- en: "Write to your own chat frame. Other players do not receive this message."
L["Help.Announces.channel.local"] = "Escreve na sua própria janela de bate-papo. Outros jogadores não recebem esta mensagem."
-- en: "Enter the message for a chat destination. The substitutions below insert action and cast information when it is available. This text is not used for Audible or named Emote output."
L["Help.Announces.text"] = "Digite a mensagem para um destino de bate-papo. As substituições abaixo inserem informações da ação e do lançamento quando disponíveis. Este texto não é usado nas saídas Sonoro nem de emote nomeado."
-- en: "For cast entries, {{spell}} is a spell link, {{item}} an item link and {{event}} the localized event name. {{target}} uses the recorded cast target, with the last recorded target for that spell as a fallback; it does not automatically use your selected target or your name. Unavailable cast substitutions can remain unchanged. Via Script/Macro instead uses its supplied target and spell, {{event}} becomes Via Script/Macro, and required missing inputs skip output; this API supplies no {{item}}."
L["Help.Announces.substitutions"] = "Em entradas de lançamento, {{spell}} é um link de feitiço, {{item}} um link de item e {{event}} o nome localizado do evento. {{target}} usa o alvo registrado do lançamento, com o último alvo registrado para esse feitiço como alternativa; não usa automaticamente seu alvo selecionado nem seu nome. Substituições de lançamento indisponíveis podem ficar inalteradas. Via script/macro usa o alvo e o feitiço fornecidos, {{event}} vira Via script/macro, e entradas obrigatórias ausentes fazem a saída ser ignorada; esta API não fornece {{item}}."
-- en: "Choose a sound supplied by the shared-media catalog, then click Play to preview it. Preview is local and does not save the draft. An unavailable sound cannot be previewed; Audible announcements require a nonempty sound selection."
L["Help.Announces.sound"] = "Escolha um som do catálogo de mídia compartilhada e clique em Reproduzir para pré-visualizá-lo. A pré-visualização é local e não salva o rascunho. Um som indisponível não pode ser pré-visualizado; anúncios sonoros exigem uma seleção de som não vazia."
-- en: "The pill turns this entry on or off while keeping its fields. Disabled entries do not announce matching casts or macro invocations. Apply saves the changed state."
L["Help.Announces.state"] = "O seletor liga ou desliga esta entrada mantendo os campos. Entradas desativadas não anunciam lançamentos nem invocações de macro correspondentes. Aplicar salva o estado alterado."
-- en: "Edits stay in a draft until Apply. Complete the action or Via Script/Macro identifier and other required fields before saving. Discard abandons changes to saved announcements; Cancel closes a new creation draft. Leaving pending changes offers Apply, Discard or Cancel navigation."
L["Help.Announces.save"] = "As edições ficam em um rascunho até Aplicar. Complete a ação ou o identificador Via script/macro e os outros campos obrigatórios antes de salvar. Descartar abandona as alterações em anúncios salvos; Cancelar fecha um rascunho de criação novo. Sair com alterações pendentes oferece navegar com Aplicar, Descartar ou Cancelar."
-- en: "Use the sidebar buttons to create, duplicate, transfer or compare announcements. Apply saves the imported draft; Compare does not merge entries. Via Script/Macro Duplicate assigns a distinct identifier and every copied output gets a fresh identity. Series exports use version 2; version 1 remains available for legacy single-output entries. Imports and Apply reject ambiguous identifiers. The red trash permanently deletes the selected saved entry after confirmation. Resolve pending edits first; deletion does not carry into the next selected draft."
L["Help.Announces.collections"] = "Use os botões da barra lateral para criar, duplicar, transferir ou comparar anúncios. Aplicar salva o rascunho importado; Comparar não mescla entradas. Duplicar em Via script/macro atribui um identificador distinto e cada saída copiada recebe uma nova identidade. Exportações de séries usam a versão 2; a versão 1 continua disponível para entradas antigas de saída única. Importações e Aplicar rejeitam identificadores ambíguos. A lixeira vermelha exclui permanentemente a entrada salva selecionada após confirmação. Resolva antes as edições pendentes; a exclusão não é levada para o próximo rascunho selecionado."
-- en: "Press Enter or leave a text field to stage its value; Apply saves the draft. Invalid text stays red and blocks navigation until corrected. Searchable selectors open on click and filter as you type. Section headings collapse or expand their contents."
L["Press Enter or leave a text field to stage its value; Apply saves the draft. Invalid text stays red and blocks navigation until corrected. Searchable selectors open on click and filter as you type. Section headings collapse or expand their contents."] = "Pressione Enter ou saia de um campo de texto para preparar o valor; Aplicar salva o rascunho. Texto inválido fica vermelho e bloqueia a navegação até ser corrigido. Seletores com busca abrem ao clicar e filtram enquanto você digita. Os cabeçalhos de seção recolhem ou expandem o conteúdo."
-- en: "An item set is an ordered list of alternatives, such as different mana potions. Runtime selection checks the list from the top for a carried or, where requested, equipped item. Priority comes from the order you choose, not the item level. Selecting an item does not by itself prove that it is usable, off cooldown, or in range; action readiness is checked separately."
L["Help.ItemSets.overview"] = "Um conjunto de itens é uma lista ordenada de alternativas, como diferentes poções de mana. A seleção em tempo de execução percorre a lista do topo em busca de um item carregado ou, quando solicitado, equipado. A prioridade vem da ordem que você escolhe, não do nível do item. Selecionar um item não prova por si só que ele pode ser usado, que está fora do tempo de recarga ou ao alcance; a prontidão da ação é verificada separadamente."
-- en: "Name the selected set so it can be found in the sidebar and referenced by rotations or conditions. New opens a name form; its first Apply saves an empty named set. Add items afterward and Apply again to save them. Discarding later item edits keeps that already saved set. Renaming a set does not change its identity in saved references."
L["Help.ItemSets.name"] = "Dê um nome ao conjunto selecionado para encontrá-lo na barra lateral e para que rotações ou condições possam referenciá-lo. Novo abre um formulário de nome; o primeiro Aplicar salva um conjunto nomeado vazio. Depois, adicione itens e use Aplicar de novo para salvá-los. Descartar edições de itens posteriores mantém o conjunto já salvo. Renomear um conjunto não altera a identidade dele nas referências salvas."
-- en: "Checked stores this set in the shared global collection, available to other profiles and characters using this addon database. Unchecked stores it in the current profile, which can itself be shared by characters. This is a staged move; Apply saves it. A profile set takes precedence if a global set has the same saved identity."
L["Help.ItemSets.global"] = "Marcado, guarda este conjunto na coleção global compartilhada, disponível para outros perfis e personagens que usam este banco de dados do addon. Desmarcado, guarda-o no perfil atual, que também pode ser compartilhado por personagens. Esta é uma mudança preparada; Aplicar a salva. Um conjunto de perfil tem precedência se um conjunto global tiver a mesma identidade salva."
-- en: "The list of item cards is the priority order. Put preferred items first. RM can leave a selection unavailable when required inventory or identity observations are missing; it does not treat unknown data as proof that a lower-priority item should be used. The sidebar icon represents the first defined item and need not be the currently carried or highlighted one."
L["Help.ItemSets.items"] = "A lista de cartões de itens é a ordem de prioridade. Coloque primeiro os itens preferidos. O RM pode deixar uma seleção indisponível quando faltam observações necessárias de inventário ou de identidade; ele não trata dados desconhecidos como prova de que um item de menor prioridade deve ser usado. O ícone da barra lateral representa o primeiro item definido e não precisa ser o que está carregado ou destacado no momento."
-- en: "Search by item name and choose a result, or drag an item from your bags or action bar into its field. The icon identifies the item; metadata can take time to load. Edit a row to replace that entry. Use its red trash can to remove it rather than clearing a required item field."
L["Help.ItemSets.item"] = "Busque pelo nome do item e escolha um resultado, ou arraste um item das suas bolsas ou da barra de ações para o campo. O ícone identifica o item; os metadados podem demorar a carregar. Edite uma linha para substituir essa entrada. Use a lixeira vermelha para removê-la em vez de apagar um campo de item obrigatório."
-- en: "Choose or drag an item into the empty item field above the list, then click Add item to append it to the priority list, or drag Add item into a gap between cards to insert it there. Entering an item in this field alone does not add a row."
L["Help.ItemSets.add"] = "Escolha ou arraste um item para o campo de item vazio acima da lista e clique em Adicionar item para acrescentá-lo à lista de prioridade, ou arraste Adicionar item para um espaço entre cartões para inseri-lo ali. Apenas digitar um item neste campo não adiciona uma linha."
-- en: "Move Up / Move Down"
L["Move Up / Move Down"] = "Mover para cima / Mover para baixo"
-- en: "Use the arrows on the left, or drag an item row into a highlighted insertion gap. Ctrl-drag moves that row and all following entries together. The floating preview identifies what you are moving. Moves past the beginning or end are unavailable. Reordering changes priority and stays in the draft until Apply."
L["Help.ItemSets.order"] = "Use as setas à esquerda ou arraste uma linha de item para um espaço de inserção destacado. Ctrl+arrastar move essa linha junto com todas as entradas seguintes. A pré-visualização flutuante identifica o que você está movendo. Movimentos além do início ou do fim ficam indisponíveis. Reordenar altera a prioridade e fica no rascunho até Aplicar."
-- en: "Bind / Unbind"
L["Bind / Unbind"] = "Vincular / Desvincular"
-- en: "Outside combat, apply pending item-set edits before binding. Drag the set (its row in the list, or the Bind pill) onto any action bar slot; an occupied slot swaps, leaving its previous action on the cursor. Or click Bind and then click an empty slot. Both pick up the first available item of the set. RM records the slot and updates it as item availability changes. The pill shows bound slot numbers; click it to unbind and remove still-matching bar items. Replaced bar actions are preserved. Binding changes are immediate action-bar operations, independent of the draft and its history."
L["Help.ItemSets.binding"] = "Fora de combate, aplique as edições pendentes do conjunto de itens antes de vincular. Arraste o conjunto (a linha dele na lista ou o seletor Vincular) para qualquer espaço da barra de ações; um espaço ocupado é trocado, deixando a ação anterior no cursor. Ou clique em Vincular e depois em um espaço vazio. Ambos pegam o primeiro item disponível do conjunto. O RM registra o espaço e o atualiza conforme a disponibilidade dos itens muda. O seletor mostra os números dos espaços vinculados; clique nele para desvincular e remover os itens da barra que ainda correspondem. As ações de barra substituídas são preservadas. Alterações de vínculo são operações imediatas na barra de ações, independentes do rascunho e do histórico dele."
-- en: "Restore the packaged item list for this set. Reset is available only for a set with a packaged default. The restored list is staged until Apply; the name is kept."
L["Help.ItemSets.reset"] = "Restaura a lista de itens incluída deste conjunto. Redefinir só está disponível para um conjunto com padrão incluído. A lista restaurada fica preparada até Aplicar; o nome é mantido."
-- en: "The red trash can at the top right permanently removes the selected saved set after confirmation. Resolve pending edits before the final warning. References in rotations or conditions then need another set. Deletion reconciles still-matching bound bar actions and keeps the set if unbinding fails; the next selection opens without an unsaved deletion marker."
L["Help.ItemSets.delete"] = "A lixeira vermelha no canto superior direito remove permanentemente o conjunto salvo selecionado após confirmação. Resolva as edições pendentes antes do aviso final. As referências em rotações ou condições passarão a precisar de outro conjunto. A exclusão concilia as ações de barra vinculadas que ainda correspondem e mantém o conjunto se a desvinculação falhar; a próxima seleção abre sem marcação de exclusão não salva."
-- en: "Undo / Redo"
L["Undo / Redo"] = "Desfazer / Refazer"
-- en: "Undo and Redo travel through recent item-set draft edits, including replacements, additions, ordering and row removals. They are unavailable when that direction has no history. Apply, Discard or leaving the page clears this bounded history. They do not reverse confirmed entity deletion or explicit action-bar binding operations."
L["Help.ItemSets.history"] = "Desfazer e Refazer percorrem as edições recentes do rascunho do conjunto de itens, incluindo substituições, adições, ordenações e remoções de linhas. Ficam indisponíveis quando não há histórico nessa direção. Aplicar, Descartar ou sair da página limpa este histórico limitado. Eles não revertem a exclusão confirmada de entidades nem operações explícitas de vínculo à barra de ações."
-- en: "Ordinary item-set edits stay in a draft until Apply. Discard restores the saved item sets. Cancel closes a new creation draft. Leaving with pending changes offers Apply, Discard or Cancel navigation. Invalid fields must be corrected before Apply; Discard can abandon them."
L["Help.ItemSets.save"] = "As edições comuns do conjunto de itens ficam em um rascunho até Aplicar. Descartar restaura os conjuntos de itens salvos. Cancelar fecha um rascunho de criação novo. Sair com alterações pendentes oferece navegar com Aplicar, Descartar ou Cancelar. Campos inválidos precisam ser corrigidos antes de Aplicar; Descartar pode abandoná-los."
-- en: "Use the buttons below the sidebar to create, duplicate, transfer, or compare sets. Duplicate makes an independent profile copy. Import shows the source name and can create a renamed copy or replace the selected list; Apply saves the staged result. Compare inspects differences without merging or modifying either set."
L["Help.ItemSets.collections"] = "Use os botões abaixo da barra lateral para criar, duplicar, transferir ou comparar conjuntos. Duplicar cria uma cópia independente no perfil. Importar mostra o nome de origem e pode criar uma cópia renomeada ou substituir a lista selecionada; Aplicar salva o resultado preparado. Comparar inspeciona as diferenças sem mesclar nem modificar nenhum dos conjuntos."
-- en: "Legacy macro buttons"
L["Legacy macro buttons"] = "Botões de macro antigos"
-- en: "Legacy clients may allow /click to invoke an RM item-set button separately from action-bar binding. The name is RM_ followed by the set name with non-alphanumeric characters removed, then an underscore and unit token. For a set named Bandages, an example is /click [@mouseover,nodead,help] RM_Bandages_mouseover. Other unit suffixes include player, pet, target, focus, pettarget, targettarget, focustarget, and mouseovertarget. These buttons contain item-use macro lines and do not provide the same readiness or first-item guarantee as the recommendation engine. Availability is subject to the client's secure-button and macro restrictions; reference-only support does not promise executable macro buttons."
L["Help.ItemSets.macros"] = "Clientes antigos podem permitir que /click invoque um botão de conjunto de itens do RM separadamente do vínculo à barra de ações. O nome é RM_ seguido do nome do conjunto sem caracteres não alfanuméricos, depois um sublinhado e um token de unidade. Para um conjunto chamado Bandages, um exemplo é /click [@mouseover,nodead,help] RM_Bandages_mouseover. Outros sufixos de unidade incluem player, pet, target, focus, pettarget, targettarget, focustarget e mouseovertarget. Esses botões contêm linhas de macro de uso de itens e não oferecem a mesma garantia de prontidão ou de primeiro item que o mecanismo de recomendação. A disponibilidade depende das restrições de botões seguros e macros do cliente; o suporte apenas de referência não promete botões de macro executáveis."
-- en: "Search for an item or drag it into the item field or icon. Choose the result to retain its exact item identity. The icon and name may be unavailable until metadata loads. Field clearing and save behavior belong to the editor that contains this list; use Delete when you intend to remove an entry."
L["Help.ItemSets.list.item"] = "Busque um item ou arraste-o para o campo ou o ícone do item. Escolha o resultado para manter a identidade exata do item. O ícone e o nome podem ficar indisponíveis até os metadados carregarem. Limpar o campo e o comportamento ao salvar dependem do editor que contém esta lista; use Excluir quando quiser remover uma entrada."
-- en: "Move this entry to the first position in the item priority list, when that control is offered."
L["Help.ItemSets.list.top"] = "Move esta entrada para a primeira posição da lista de prioridade de itens, quando esse controle estiver disponível."
-- en: "Move this entry one position earlier. A move before the first entry is unavailable."
L["Help.ItemSets.list.up"] = "Move esta entrada uma posição para cima. Não é possível mover acima da primeira entrada."
-- en: "Move this entry one position later. A move past the final entry is unavailable."
L["Help.ItemSets.list.down"] = "Move esta entrada uma posição para baixo. Não é possível mover abaixo da última entrada."
-- en: "Move this entry to the final position in the item priority list, when that control is offered."
L["Help.ItemSets.list.bottom"] = "Move esta entrada para a última posição da lista de prioridade de itens, quando esse controle estiver disponível."
-- en: "Remove this entry from the list. In a draft editor this remains pending until Apply, and Discard abandons the row edit. Undo is available where the containing editor provides draft history. This differs from permanently deleting the entire set after confirmation."
L["Help.ItemSets.list.delete"] = "Remove esta entrada da lista. Em um editor com rascunho, isso fica pendente até Aplicar, e Descartar abandona a edição da linha. Desfazer está disponível quando o editor que contém a lista oferece histórico do rascunho. Isso é diferente de excluir permanentemente o conjunto inteiro após confirmação."
-- en: "Default rotation view"
L["Default rotation view"] = "Visualização padrão da rotação"
-- en: "Choose Diagram or List as the starting rotation view. This profile preference applies when opening a rotation; changing the view inside the editor does not change this setting. Cooldowns always use a scrolling grid."
L["Choose Diagram or List as the starting rotation view. This profile preference applies when opening a rotation; changing the view inside the editor does not change this setting. Cooldowns always use a scrolling grid."] = "Escolha Diagrama ou Lista como visualização inicial da rotação. Esta preferência do perfil se aplica ao abrir uma rotação; alterar a visualização dentro do editor não muda esta configuração. Os tempos de recarga sempre usam uma grade com rolagem."
-- en: "Reset diagram zoom to 100%. Scroll to zoom; middle-click to reset. Drag empty space to pan."
L["Reset diagram zoom to 100%. Scroll to zoom; middle-click to reset. Drag empty space to pan."] = "Redefine o zoom do diagrama para 100%. Role para aplicar zoom; clique com o botão do meio para redefinir. Arraste o espaço vazio para deslocar."
-- en: "Move this and following entries"
L["Move this and following entries"] = "Mover esta entrada e as seguintes"
-- en: "Drag one entry; Ctrl-drag moves it and all following siblings."
L["Drag one entry; Ctrl-drag moves it and all following siblings."] = "Arraste uma entrada; Ctrl+arrastar a move junto com todos os irmãos seguintes."
-- en: "%d cards"
L["%d cards"] = "%d cartões"
-- en: " (%d hidden)"
L[" (%d hidden)"] = " (%d ocultos)"
-- en: "Click to fold or unfold this branch arm. Other cards and conditions are unchanged."
L["Click to fold or unfold this branch arm. Other cards and conditions are unchanged."] = "Clique para recolher ou expandir este braço da ramificação. Os outros cartões e condições não mudam."
-- en: "%s totem {{!is|is not}} active"
L["%s totem {{!is|is not}} active"] = "o totem de %s {{!está|não está}} ativo"
-- en: "%s {{!are|are not}} %s"
L["%s {{!are|are not}} %s"] = "%s {{!é|não é}} %s"
-- en: "%s {{!are|are not}} PVP flagged"
L["%s {{!are|are not}} PVP flagged"] = "%s {{!está|não está}} marcado para JxJ"
-- en: "%s {{!are|are not}} a %s"
L["%s {{!are|are not}} a %s"] = "%s {{!é|não é}} %s"
-- en: "%s {{!are|are not}} currently casting"
L["%s {{!are|are not}} currently casting"] = "%s {{!está|não está}} lançando um feitiço"
-- en: "%s {{!are|are not}} currently casting %s"
L["%s {{!are|are not}} currently casting %s"] = "%s {{!está|não está}} lançando %s"
-- en: "{unit} {{!are|are not}} currently casting {spell}"
L["{unit} {{!are|are not}} currently casting {spell}"] = "{unit} {{!está|não está}} lançando {spell}"
-- en: "%s {{!are|are not}} currently channeling"
L["%s {{!are|are not}} currently channeling"] = "%s {{!está|não está}} canalizando"
-- en: "%s {{!are|are not}} currently channeling %s"
L["%s {{!are|are not}} currently channeling %s"] = "%s {{!está|não está}} canalizando %s"
-- en: "{unit} {{!are|are not}} currently channeling {spell}"
L["{unit} {{!are|are not}} currently channeling {spell}"] = "{unit} {{!está|não está}} canalizando {spell}"
-- en: "%s {{!are|are not}} in combat"
L["%s {{!are|are not}} in combat"] = "%s {{!está|não está}} em combate"
-- en: "%s {{!has|does not have}} %s"
L["%s {{!has|does not have}} %s"] = "%s {{!tem|não tem}} %s"
-- en: "%s {{!has|does not have}} a %s debuff"
L["%s {{!has|does not have}} a %s debuff"] = "%s {{!tem|não tem}} uma penalidade de %s"
-- en: "%s {{!has|does not have}} a stealable buff"
L["%s {{!has|does not have}} a stealable buff"] = "%s {{!tem|não tem}} um bônus roubável"
-- en: "%s {{!have|do not have}} %s"
L["%s {{!have|do not have}} %s"] = "%s {{!tem|não tem}} %s"
-- en: "%s {{!have|do not have}} %s where %s"
L["%s {{!have|do not have}} %s where %s"] = "%s {{!tem|não tem}} %s em que %s"
-- en: "%s {{!have|do not have}} a %s debuff"
L["%s {{!have|do not have}} a %s debuff"] = "%s {{!tem|não tem}} uma penalidade de %s"
-- en: "%s {{!is|is not}} %s"
L["%s {{!is|is not}} %s"] = "%s {{!é|não é}} %s"
-- en: "%s {{!is|is not}} PVP flagged"
L["%s {{!is|is not}} PVP flagged"] = "%s {{!está|não está}} marcado para JxJ"
-- en: "%s {{!is|is not}} a %s"
L["%s {{!is|is not}} a %s"] = "%s {{!é|não é}} %s"
-- en: "%s {{!is|is not}} active"
L["%s {{!is|is not}} active"] = "%s {{!está|não está}} ativo"
-- en: "%s {{!is|is not}} active or pending"
L["%s {{!is|is not}} active or pending"] = "%s {{!está|não está}} ativo ou pendente"
-- en: "%s {{!is|is not}} active with %s"
L["%s {{!is|is not}} active with %s"] = "%s {{!está|não está}} ativo com %s"
-- en: "%s {{!is|is not}} an enemy"
L["%s {{!is|is not}} an enemy"] = "%s {{!é|não é}} um inimigo"
-- en: "%s {{!is|is not}} attackable"
L["%s {{!is|is not}} attackable"] = "%s {{!é|não é}} atacável"
-- en: "%s {{!is|is not}} available"
