-- en: "Weapon Imbue"
L["Weapon Imbue"] = "Imbuição de arma"
-- en: "Absolute health target (negative means deficit) or percentage fraction."
L["Absolute health target (negative means deficit) or percentage fraction."] = "Alvo de vida absoluto (negativo significa déficit) ou fração percentual."
